{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/cart-list.json
    The lines of a cart as a table or as cards: product, variant, price, quantity, line total and a remove button. Axes: layout (table, cards), media (image, none), density, tone.
    Props (p): id, title, lines, labels, layout, media, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_lines = (p.lines ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_layout = (p.layout ?? 'table') -%}
{%- set v_media = (p.media ?? 'image') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_10 -%}
  {%- if ui_t(ui_eq(v_layout, 'table')) %}
    {{ include('blocks/cart-table.html.twig', {'p': {'field': ui_tpl('{0}-qty', [v_id]), 'lines': v_lines, 'labels': v_labels, 'media': v_media, 'density': v_density}}, with_context = false) }}
  {%- else %}
    {%- set c_9 -%}
      {%- for v_line in ui_l(v_lines) %}
        {%- set c_8 -%}
          {%- set c_7 -%}
            {%- if ui_t(ui_eq(v_media, 'image')) %}
              {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_line, ['name']), 'ratio': '1/1', 'className': ui_cnv(['size-16 shrink-0'])}}, with_context = false) }}
            {%- endif %}
            {%- set c_4 -%}
              {%- set c_1 -%}
                {{ ui_text(ui_get(v_line, ['name'])) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_1}, with_context = false) }}
              {%- set c_2 -%}
                {{ ui_text(ui_get(v_line, ['variant'])) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_2}, with_context = false) }}
              {%- set c_3 -%}
                {{ ui_text(ui_money(ui_get(v_line, ['price']), ui_get(v_line, ['currency']))) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm'}, 'children': c_3}, with_context = false) }}
            {%- endset -%}
            {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '0', 'Class': 'min-w-40 flex-1'}, 'children': c_4}, with_context = false) }}
            {{ include('blocks/number-field.html.twig', {'p': {'value': ui_str(ui_get(v_line, ['qty'])), 'name': ui_tpl('{0}-qty-{1}', [v_id, ui_get(v_line, ['id'])]), 'min': '1', 'label': ui_get(v_labels, ['qty']), 'decrease': ui_get(v_labels, ['decrease']), 'increase': ui_get(v_labels, ['increase'])}}, with_context = false) }}
            {%- set c_5 -%}
              {{ ui_text(ui_money(ui_mul(ui_get(v_line, ['price']), ui_get(v_line, ['qty'])), ui_get(v_line, ['currency']))) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'base', 'Weight': 'bold'}, 'children': c_5}, with_context = false) }}
            {%- set c_6 -%}
              {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'x', 'Size': 16}}, with_context = false) }}
            {%- endset -%}
            {{ include('ui/button/button.html.twig', {'p': {'Variant': 'ghost', 'Size': 'sm', 'Layout': 'icon', 'AriaLabel': ui_s(ui_get(v_labels, ['remove'])), 'Attrs': ui_attrs(['data-testid', 'remove'])}, 'children': c_6}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/card/card-content.html.twig', {'p': {'Class': 'flex flex-wrap items-center gap-4'}, 'children': c_7}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/card/card.html.twig', {'p': {'Variant': 'default', 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_8}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '4', 'Align': 'stretch', 'Attrs': ui_attrs(['data-testid', 'cart-cards'])}, 'children': c_9}, with_context = false) }}
  {%- endif %}
{%- endset -%}
{{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': c_10}, with_context = false) }}
